20	constexpr int BLOCK_M = 64;   // query rows per block
21	constexpr int BLOCK_N = 64;   // key/value rows per tile
22	constexpr int HEAD_DIM = 128;
23	constexpr int NUM_WARPS = 8;
24	constexpr int NUM_THREADS = NUM_WARPS * 32;
25	constexpr int ROWS_PER_WARP = BLOCK_M / NUM_WARPS;  // 8
26	constexpr int D_PER_LANE = HEAD_DIM / 32;           // 4
27	
28	__device__ __forceinline__ float warp_sum(float v) {
29	#pragma unroll
30	    for (int offset = 16; offset > 0; offset >>= 1)
31	        v += __shfl_xor_sync(0xffffffffu, v, offset);
32	    return v;
33	}
