// Probe: verify ldmatrix fragment layouts against PTX docs.
// Fills sK[64][128] and sV[64][128] with deterministic values, runs
// ldmatrix.x2 (B frag for S matmul) and ldmatrix.x4.trans (B frag for O
// matmul), and prints per-thread fragments for manual verification.
#include <cstdio>
#include <cstdint>
#include <cuda_fp16.h>
#include <cuda_bf16.h>

__device__ __forceinline__ void ldmatrix_x2(uint32_t r[2], const void* smem_ptr) {
  uint32_t addr = (uint32_t)__cvta_generic_to_shared(smem_ptr);
  asm volatile("ldmatrix.sync.aligned.m8n8.x2.shared.b16 {%0,%1}, [%2];\n"
               : "=r"(r[0]), "=r"(r[1]) : "r"(addr));
}
__device__ __forceinline__ void ldmatrix_x4(uint32_t r[4], const void* smem_ptr) {
  uint32_t addr = (uint32_t)__cvta_generic_to_shared(smem_ptr);
  asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
               : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3]) : "r"(addr));
}
__device__ __forceinline__ void ldmatrix_x4_trans(uint32_t r[4], const void* smem_ptr) {
  uint32_t addr = (uint32_t)__cvta_generic_to_shared(smem_ptr);
  asm volatile("ldmatrix.sync.aligned.m8n8.x4.trans.shared.b16 {%0,%1,%2,%3}, [%4];\n"
               : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3]) : "r"(addr));
}

__global__ void probe_kernel() {
  __shared__ __align__(16) __nv_bfloat16 sK[64][128];
  __shared__ __align__(16) __nv_bfloat16 sV[64][128];
  const int tid = threadIdx.x;

  // deterministic fill: sK[n][k] = n * 1000 + k ; sV[n][k] = n * 1000 + k + 50000
  for (int i = tid; i < 64 * 128 / 8; i += blockDim.x) {
    int row = i / 16, col8 = (i % 16) * 8;
    for (int j = 0; j < 8; ++j) {
      sK[row][col8 + j] = __float2bfloat16((float)(row * 1000 + col8 + j));
      sV[row][col8 + j] = __float2bfloat16((float)(row * 1000 + col8 + j + 50000));
    }
  }
  __syncthreads();

  if (tid >= 32) return;
  const int g = tid >> 2, l = tid & 3;

  // Test 1: B fragment for S matmul via ldmatrix.x2 NON-trans on natural sK.
  // Addresses: threads 0-7 -> &sK[t][16j]; threads 8-15 -> &sK[t-8][16j+8].
  // Expect r[0] = (K[g][16j+2l], K[g][16j+2l+1]), r[1] = (K[g][16j+2l+8], K[g][16j+2l+9]).
  {
    const int j = 2; // head col base 32
    const void* addr0 = (tid < 8)  ? (const void*)&sK[tid][16 * j]
                       : (const void*)&sK[tid - 8][16 * j + 8];
    uint32_t r[2];
    ldmatrix_x2(r, addr0);
    uint16_t lo0 = r[0] & 0xffff, hi0 = r[0] >> 16;
    uint16_t lo1 = r[1] & 0xffff, hi1 = r[1] >> 16;
    float e0 = __bfloat162float(sK[g][16 * j + 2 * l]);
    float e1 = __bfloat162float(sK[g][16 * j + 2 * l + 1]);
    float e2 = __bfloat162float(sK[g][16 * j + 2 * l + 8]);
    float e3 = __bfloat162float(sK[g][16 * j + 2 * l + 9]);
    bool ok = (__bfloat16_as_ushort(__float2bfloat16(e0)) == lo0) &&
              (__bfloat16_as_ushort(__float2bfloat16(e1)) == hi0) &&
              (__bfloat16_as_ushort(__float2bfloat16(e2)) == lo1) &&
              (__bfloat16_as_ushort(__float2bfloat16(e3)) == hi1);
    if (tid == 0) printf("Test1 (S B-frag, ldmatrix.x2 natural sK): %s\n", ok ? "PASS" : "FAIL");
    if (!ok && g < 2) printf("  T1 fail tid=%d g=%d l=%d got(%04x,%04x,%04x,%04x) exp(%04x,%04x,%04x,%04x)\n",
        tid, g, l, lo0, hi0, lo1, hi1,
        __bfloat16_as_ushort(__float2bfloat16(e0)), __bfloat16_as_ushort(__float2bfloat16(e1)),
        __bfloat16_as_ushort(__float2bfloat16(e2)), __bfloat16_as_ushort(__float2bfloat16(e3)));
  }

  // Test 2: B fragment for O matmul via ldmatrix.x4.trans on natural sV.
  // Addresses: threads 0-7 -> &sV[t][8j']; 8-15 -> &sV[t-8][8j'];
  //            16-23 -> &sV[t-16+8][8j']; 24-31 -> &sV[t-24+8][8j']  (rows 8..15)
  // Expect r[0] = (V[2l][8j'+g], V[2l+1][8j'+g])   r[1] = (V[2l+8][8j'+g], V[2l+9][8j'+g])
  //        r[2] = (V[2l][8j'+g], V[2l+1][8j'+g])?? -> need to check ordering
  {
    const int jj = 1; // head col base 8
    const void* addr0;
    if (tid < 8)       addr0 = (const void*)&sV[tid][8 * jj];
    else if (tid < 16) addr0 = (const void*)&sV[tid - 8][8 * jj];
    else if (tid < 24) addr0 = (const void*)&sV[tid - 16 + 8][8 * jj];
    else               addr0 = (const void*)&sV[tid - 24 + 8][8 * jj];
    uint32_t r[4];
    ldmatrix_x4_trans(r, addr0);
    // candidate: r0 = (V[2l][8j+g], V[2l+1][8j+g]), r1 = (V[2l+8][...], V[2l+9][...])
    uint16_t a0 = r[0] & 0xffff, b0 = r[0] >> 16;
    uint16_t a1 = r[1] & 0xffff, b1 = r[1] >> 16;
    uint16_t a2 = r[2] & 0xffff, b2 = r[2] >> 16;
    uint16_t a3 = r[3] & 0xffff, b3 = r[3] >> 16;
    float v0 = __bfloat162float(sV[2 * l][8 * jj + g]);
    float v1 = __bfloat162float(sV[2 * l + 1][8 * jj + g]);
    float v8 = __bfloat162float(sV[2 * l + 8][8 * jj + g]);
    float v9 = __bfloat162float(sV[2 * l + 9][8 * jj + g]);
    bool ok0 = (__bfloat16_as_ushort(__float2bfloat16(v0)) == a0) &&
               (__bfloat16_as_ushort(__float2bfloat16(v1)) == b0);
    bool ok1 = (__bfloat16_as_ushort(__float2bfloat16(v8)) == a1) &&
               (__bfloat16_as_ushort(__float2bfloat16(v9)) == b1);
    if (tid == 0) printf("Test2 (O B-frag, ldmatrix.x4.trans natural sV): %s\n", ok0 && ok1 ? "PASS" : "FAIL");
    if ((!ok0 || !ok1) && g < 2) printf("  T2 tid=%d g=%d l=%d got(%04x,%04x,%04x,%04x,%04x,%04x,%04x,%04x)\n",
        tid, g, l, a0, b0, a1, b1, a2, b2, a3, b3);
    // r2/r3 candidates: (V[2l][8j+g+8]...)? print mapping
    if (tid == 0) printf("  T2 note: r2=(%04x,%04x) r3=(%04x,%04x)\n", a2, b2, a3, b3);
  }
}

int main() {
  probe_kernel<<<1, 128>>>();
  cudaDeviceSynchronize();
