              (__bfloat16_as_ushort(__float2bfloat16(q5)) == b2) &&
              (__bfloat16_as_ushort(__float2bfloat16(q6)) == a3) &&
              (__bfloat16_as_ushort(__float2bfloat16(q7)) == b3);
    if (tid == 0) printf("Test3 (Q A-frag, ldmatrix.x4 natural sK): %s\n", ok ? "PASS" : "FAIL");
    if (!ok && g < 2) printf("  T3 tid=%d g=%d l=%d got(%04x,%04x,%04x,%04x,%04x,%04x,%04x,%04x)\n",
        tid, g, l, a0, b0, a1, b1, a2, b2, a3, b3);
  }
}

