__device__ __forceinline__ uint32_t pack(float lo, float hi) {
  uint16_t e0 = __bfloat16_as_ushort(__float2bfloat16(lo));
  uint16_t e1 = __bfloat16_as_ushort(__float2bfloat16(hi));
  return (uint32_t)e0 | ((uint32_t)e1 << 16);
