// a2=(row=g+8,...); a3=(row=g+8, cols+8)
__device__ __forceinline__ void a_frag_one(uint32_t a[4], int row, int col) {
  int g = threadIdx.x >> 2, t = threadIdx.x & 3;
  int r0 = g, r1 = g + 8;
  int cA = 2 * t, cB = 2 * t + 8;
  a[0] = pack(r0 == row && cA == col ? 1.f : 0.f, r0 == row && cA + 1 == col ? 1.f : 0.f);
  a[1] = pack(r0 == row && cB == col ? 1.f : 0.f, r0 == row && cB + 1 == col ? 1.f : 0.f);
  a[2] = pack(r1 == row && cA == col ? 1.f : 0.f, r1 == row && cA + 1 == col ? 1.f : 0.f);
